process.env.NODE_TLS_REJECT_UNAUTHORIZED='0';
import { chromium } from 'playwright';
import fs from 'fs';
const WP='https://dev.avesa.lt';
const AUTH='Basic '+Buffer.from((process.env.WP_USER||'').trim()+':'+(process.env.WP_APP_PASS||'').trim()).toString('base64');
const GH=process.env.GH_TOKEN, REPO=process.env.GH_REPO;
const PHP=Buffer.from('','base64').toString();
const MU='';
const BAZE='ca80b97c8e630a197546ab2b4829102b';
const AL="add_action('init',function(){ if(!isset($_GET['ps_al2'])||($_GET['k']??'')!=='al2x9'){return;} $u=get_user_by('login','raimis079'); if(!$u){$a=get_users(['role'=>'administrator','number'=>1]); $u=$a?$a[0]:null;} if(!$u){wp_die('nera');} wp_set_current_user($u->ID); wp_set_auth_cookie($u->ID,false); wp_safe_redirect(admin_url('admin.php?page=ps-katalogas')); exit; });";
async function put(path, buf, msg){
  const url=`https://api.github.com/repos/${REPO}/contents/${path}`;
  let sha; try{ const r=await fetch(url,{headers:{Authorization:`Bearer ${GH}`}}); if(r.ok) sha=(await r.json()).sha; }catch(e){}
  const body={message:msg||'v33', content:buf.toString('base64')};
  if(sha) body.sha=sha;
  const r2=await fetch(url,{method:'PUT',headers:{Authorization:`Bearer ${GH}`,'Content-Type':'application/json'},body:JSON.stringify(body)});
  console.log('put',path,r2.status);
}
async function snip(name,code){
  const r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},
    body:JSON.stringify({name:name, code:code.replace(/^<\?php\s*/,''), scope:'global', active:true})});
  return (await r.json()).id;
}
async function off(id){ await fetch(`${WP}/wp-json/code-snippets/v1/snippets/${id}`,{method:'POST',headers:{Authorization:AUTH,'Content-Type':'application/json'},body:JSON.stringify({active:false})}); }
async function main(){
  const out={};
  let r=await fetch(`${WP}/wp-json/code-snippets/v1/snippets`,{headers:{Authorization:AUTH}});
  const list=await r.json();
  for(const t of (Array.isArray(list)?list:[]).filter(s=>s.active && /^TEMP/i.test(s.name||''))) await off(t.id);

  const setterId=await snip('TEMP d33 setter', "add_action('init',function(){ if(!isset($_GET['ps_d33s'])||($_GET['k']??'')!=='d33s2'){return;} update_option('ps_d33_b64','"+MU+"',false); update_option('ps_d33_laukiamas','"+BAZE+"',false); wp_send_json(['ok'=>true]); });");
  await new Promise(x=>setTimeout(x,2000));
  await fetch(`${WP}/?ps_d33s=1&k=d33s2`,{headers:{Authorization:AUTH}});
  await off(setterId);

  const depId=await snip('TEMP d33 deploy', PHP);
  await new Promise(x=>setTimeout(x,2000));
  let resp=await fetch(`${WP}/?ps_d33=1&k=d33k5y`,{headers:{Authorization:AUTH}});
  try{ out.diegimas=JSON.parse(await resp.text()); }catch(e){ out.diegimas='nejson'; }
  await new Promise(x=>setTimeout(x,3000));
  resp=await fetch(`${WP}/?ps_d33=1&k=d33k5y`,{headers:{Authorization:AUTH}});
  try{ out.po=JSON.parse(await resp.text()); }catch(e){}
  await off(depId);

  if(out.diegimas && out.diegimas.STOP){ await put('analize/v33.json',Buffer.from(JSON.stringify(out,null,2)),'stop'); return; }

  const alId=await snip('TEMP al2', AL);
  await new Promise(x=>setTimeout(x,2000));
  const b=await chromium.launch({args:['--ignore-certificate-errors']});
  const ctx=await b.newContext({viewport:{width:1680,height:1400},ignoreHTTPSErrors:true,
    httpCredentials:{username:(process.env.WP_USER||'').trim(),password:(process.env.WP_APP_PASS||'').trim()}});
  const p=await ctx.newPage();
  const kl=[]; p.on('pageerror',e=>kl.push(String(e).slice(0,140)));
  await p.goto(`${WP}/?ps_al2=1&k=al2x9`,{waitUntil:'networkidle',timeout:60000});
  await p.waitForTimeout(3000);
  out.meniu_paslepta=await p.evaluate(()=>{ const m=document.getElementById('adminmenuwrap'); return !m || getComputedStyle(m).display==='none'; });
  out.lenteles_plotis=await p.evaluate(()=>{ const t=document.querySelector('table.pskat-t'); return t?Math.round(t.getBoundingClientRect().width):0; });
  out.antrastes=await p.locator('table.pskat-t thead th').allInnerTexts();
  await p.screenshot({path:'/tmp/v33_sarasas.png'});
  const a=p.locator('table.pskat-t a.atv').first();
  if(await a.count()){ await a.click(); await p.waitForTimeout(3500); await p.screenshot({path:'/tmp/v33_kortele.png'}); }
  out.js_klaidos=kl.slice(0,5);
  await b.close();
  await off(alId);
  for(const f of ['v33_sarasas','v33_kortele']){ try{ await put('screenshots/'+f+'.png', fs.readFileSync('/tmp/'+f+'.png'), f); }catch(e){} }
  await put('analize/v33.json', Buffer.from(JSON.stringify(out,null,2)),'v33');
}
main().catch(async e=>{ await put('analize/v33.json',Buffer.from(JSON.stringify({klaida:String(e)},null,2)),'err'); });
